import math
from numbers import Real


def humidex_celsius(temperature, dewpoint):
    if not isinstance(temperature, Real) or isinstance(temperature, bool):
        raise TypeError("temperature must be a real number")
    if not isinstance(dewpoint, Real) or isinstance(dewpoint, bool):
        raise TypeError("dewpoint must be a real number")
    temperature = float(temperature)
    dewpoint = float(dewpoint)
    if not math.isfinite(temperature) or not math.isfinite(dewpoint):
        return math.nan
    if temperature < 20.0 or dewpoint > temperature:
        return math.nan
    vapor_pressure = 6.11 * math.exp(
        5417.7530 * (1.0 / 273.16 - 1.0 / (dewpoint + 273.0))
    )
    return temperature + 0.5555 * (vapor_pressure - 10.0)

